type Config struct Spu SpuConfig `mapstructure:&quot;spu&quot;` Sdks []SDKConf `mapstructure:&quot;sdks&quot;` // SpiHttpClients SpiHttpClientConfig `mapstructure:&quot;spi_http_clients&quot;` Person // MockConfig `mapstructure:&quot;,squash&quot;` // }
